local ServingPlateMaker = {}
local PRODUCTS = {
    simple_pewter_plate = { name = "Preprosta kositrna plošča", tinCost = 2, time = 3, cost = 35, culinary = 18, happiness = 1, description = "Preprosta kositrna plošča za jedilnico." },
    ceramic_painted_plate = { name = "Keramična poslikana plošča", clayCost = 2, paintCost = 1, glassCost = 1, time = 5, cost = 100, culinary = 32, happiness = 1, prestige = 2, description = "Keramična poslikana plošča za trgovce." },
    silver_dinner_plate = { name = "Srebrna večerja plošča", silverCost = 2, tinCost = 1, time = 8, cost = 260, culinary = 48, happiness = 2, prestige = 6, description = "Srebrna večerja plošča za plemiče." },
    gold_trimmed_charger = { name = "Zlatookrasni podstavek", goldCost = 1, silverCost = 2, tinCost = 1, time = 12, cost = 620, culinary = 62, happiness = 3, prestige = 14, description = "Zlatookrasni podstavek za visoke plemiče." },
    jewel_edged_platter = { name = "Draguljasta pladenj", goldCost = 2, silverCost = 1, tinCost = 1, jewelCost = 1, time = 16, cost = 1400, culinary = 78, happiness = 5, prestige = 27, description = "Pladenj z draguljastim robom za visoko plemstvo." },
    royal_grand_serving_set = { name = "Kraljevski veliki servisirni set", goldCost = 3, silverCost = 2, tinCost = 1, jewelCost = 2, pearlCost = 2, time = 23, cost = 3200, culinary = 92, happiness = 12, prestige = 56, description = "Veliki kraljevski servisirni set z biseri in zlatom za kronanje." },
}
local BUILDINGS = {
    plate_workshop = { name = "Ploščna delavnica", cost = { gold = 220, wood = 100, stone = 120, tin = 6 }, upkeep = 5, qualityBonus = 5 },
    porcelain_loft = { name = "Porcelanasta podstrešje", cost = { gold = 820, wood = 240, stone = 240, clay = 8, paint = 6 }, upkeep = 19, qualityBonus = 18 },
    master_platemaker_atelier = { name = "Mojstrski ploščni atelje", cost = { gold = 2400, wood = 360, stone = 480, silver = 30, gold = 6 }, upkeep = 55, qualityBonus = 30 },
    royal_tableware_palace = { name = "Kraljevska jedilna palača", cost = { gold = 9800, wood = 580, stone = 740, gold = 60, jewel = 16 }, upkeep = 195, qualityBonus = 55, prestigeBonus = 50 },
}
ServingPlateMaker.tinStock = 14; ServingPlateMaker.clayStock = 10; ServingPlateMaker.paintStock = 10; ServingPlateMaker.glassStock = 8; ServingPlateMaker.silverStock = 6; ServingPlateMaker.goldStock = 6; ServingPlateMaker.jewelStock = 4; ServingPlateMaker.pearlStock = 4
ServingPlateMaker.productStock = {}; ServingPlateMaker.buildings = {}; ServingPlateMaker.maker = nil; ServingPlateMaker.activeMaking = {}; ServingPlateMaker.totalProducts = 0; ServingPlateMaker.dayTimer = 0
function ServingPlateMaker.init() ServingPlateMaker.tinStock=14; ServingPlateMaker.clayStock=10; ServingPlateMaker.paintStock=10; ServingPlateMaker.glassStock=8; ServingPlateMaker.silverStock=6; ServingPlateMaker.goldStock=6; ServingPlateMaker.jewelStock=4; ServingPlateMaker.pearlStock=4; ServingPlateMaker.productStock={}; ServingPlateMaker.buildings={}; ServingPlateMaker.maker=nil; ServingPlateMaker.activeMaking={}; ServingPlateMaker.totalProducts=0; ServingPlateMaker.dayTimer=0; print("[ServingPlateMaker] Royal Serving Plate Maker System initialized (6 products, 4 buildings)") end
function ServingPlateMaker.hireMaker(n,s) s=s or math.random(55,90); local c=480+s*11; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; ServingPlateMaker.maker={name=n or ("Ploščar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Ploščar najet: %s (spretnost: %d)",ServingPlateMaker.maker.name,s),"success") end; return true end
function ServingPlateMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function ServingPlateMaker.build(id) local ok,e=ServingPlateMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(ServingPlateMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function ServingPlateMaker.getQualityBonus() local b=0; for _,bd in ipairs(ServingPlateMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function ServingPlateMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.tinCost and ServingPlateMaker.tinStock<(d.tinCost or 0) then return false,"Premalo kositra" end; if d.clayCost and ServingPlateMaker.clayStock<(d.clayCost or 0) then return false,"Premalo gline" end; if d.paintCost and ServingPlateMaker.paintStock<(d.paintCost or 0) then return false,"Premalo barve" end; if d.glassCost and ServingPlateMaker.glassStock<(d.glassCost or 0) then return false,"Premalo stekla" end; if d.silverCost and ServingPlateMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and ServingPlateMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and ServingPlateMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and ServingPlateMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #ServingPlateMaker.buildings==0 then return false,"Potrebna ploščna delavnica" end; if not ServingPlateMaker.maker then return false,"Potreben ploščar" end; return true end
function ServingPlateMaker.make(pt,qty) qty=qty or 1; local ok,e=ServingPlateMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.tinCost then ServingPlateMaker.tinStock=ServingPlateMaker.tinStock-d.tinCost*qty end; if d.clayCost then ServingPlateMaker.clayStock=ServingPlateMaker.clayStock-d.clayCost*qty end; if d.paintCost then ServingPlateMaker.paintStock=ServingPlateMaker.paintStock-d.paintCost*qty end; if d.glassCost then ServingPlateMaker.glassStock=ServingPlateMaker.glassStock-d.glassCost*qty end; if d.silverCost then ServingPlateMaker.silverStock=ServingPlateMaker.silverStock-d.silverCost*qty end; if d.goldCost then ServingPlateMaker.goldStock=ServingPlateMaker.goldStock-d.goldCost*qty end; if d.jewelCost then ServingPlateMaker.jewelStock=ServingPlateMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then ServingPlateMaker.pearlStock=ServingPlateMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if ServingPlateMaker.maker then t=math.max(1,t-math.floor(ServingPlateMaker.maker.skill/13)) end; table.insert(ServingPlateMaker.activeMaking,{id="plate_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,culinary=d.culinary or 0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function ServingPlateMaker.completeMaking(m) local q=1.0+(ServingPlateMaker.getQualityBonus()/100); if ServingPlateMaker.maker then q=q+(ServingPlateMaker.maker.skill/150) end; q=math.min(2.4,q); ServingPlateMaker.productStock[m.productType]=(ServingPlateMaker.productStock[m.productType] or 0)+m.quantity; ServingPlateMaker.totalProducts=ServingPlateMaker.totalProducts+m.quantity; if m.culinary>0 and _G.state then _G.state.culinary=(_G.state.culinary or 0)+m.culinary end; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if ServingPlateMaker.maker then ServingPlateMaker.maker.itemsMade=ServingPlateMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then ServingPlateMaker.maker.skill=math.min(100,ServingPlateMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Plošča izdelana: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"plate.completed",{productName=m.productName,culinary=m.culinary,prestige=m.prestige,happiness=m.happiness}) end end
function ServingPlateMaker.update(dt) if not _G.state then return end; ServingPlateMaker.dayTimer=ServingPlateMaker.dayTimer+dt; if ServingPlateMaker.dayTimer>=30 then ServingPlateMaker.dayTimer=0; for i=#ServingPlateMaker.activeMaking,1,-1 do local m=ServingPlateMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then ServingPlateMaker.completeMaking(m); table.remove(ServingPlateMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(ServingPlateMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if ServingPlateMaker.maker then tu=tu+13 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function ServingPlateMaker.getStats() return {tinStock=ServingPlateMaker.tinStock,clayStock=ServingPlateMaker.clayStock,paintStock=ServingPlateMaker.paintStock,glassStock=ServingPlateMaker.glassStock,silverStock=ServingPlateMaker.silverStock,goldStock=ServingPlateMaker.goldStock,jewelStock=ServingPlateMaker.jewelStock,pearlStock=ServingPlateMaker.pearlStock,productStock=ServingPlateMaker.productStock,numBuildings=#ServingPlateMaker.buildings,hasMaker=ServingPlateMaker.maker~=nil,makerName=ServingPlateMaker.maker and ServingPlateMaker.maker.name or "—",makerSkill=ServingPlateMaker.maker and ServingPlateMaker.maker.skill or 0,activeMaking=#ServingPlateMaker.activeMaking,totalProducts=ServingPlateMaker.totalProducts} end
return ServingPlateMaker
